"use client";

import React, { useId } from "react";
import type { StickerProps } from "../types";
import { usePeel } from "../utils/usePeel";

const IMAGE = "data:image/png;base64,";

/**
 * Kawaii Japanese-style cat sticker traced from the Catbeats die-cut artwork.
 * The original reference pixels are embedded as a lossless PNG.
 *
 * @example
 * <CatbeatsSticker size={140} peel />
 */
export const CatbeatsSticker: React.FC<StickerProps> = ({
  size = 100,
  width,
  height,
  peel = false,
  className = "",
  style,
  ...props
}) => {
  const rawId = useId();
  const id = rawId.replace(/[:]/g, "_");
  const { style: peelStyle, onMouseEnter, onMouseLeave } = usePeel(peel, style);

  return (
    <svg
      width={width ?? size}
      height={height ?? size}
      viewBox="0 0 437 532"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className={`${id}-root ${className}`}
      style={peelStyle}
      onMouseEnter={onMouseEnter}
      onMouseLeave={onMouseLeave}
      role="img"
      aria-label="Catbeats Cat Sticker"
      {...props}
    >
      <style>{`
        @keyframes ${id}-float {
          0%, 100% { transform: translateY(0) rotate(-1deg); }
          50% { transform: translateY(-5px) rotate(1deg); }
        }
        .${id}-art { transform-origin: 218px 500px; }
        @media (prefers-reduced-motion: no-preference) {
          .${id}-art { animation: ${id}-float 4.2s ease-in-out infinite; }
          .${id}-root:hover .${id}-art { animation-duration: 1.8s; }
        }
      `}</style>
      <g className={`${id}-art`}>
        <image href={IMAGE} x={0} y={0} width="437" height="532" />
      </g>
    </svg>
  );
};

export default CatbeatsSticker;

